<template><view class="auth-page"><view class="back" @tap="back">‹</view><view class="auth-icon">绿</view><text class="title">创建账号</text><text class="subtitle">加入碳宝星球，开启绿色之旅。</text><view class="form"><text class="label">用户名</text><input class="input" placeholder="请输入唯一用户名" v-model="username"/><text class="label">密码</text><input class="input" password placeholder="请创建密码" v-model="password"/><text class="label">身份类型</text><view class="roles"><view v-for="role in roles" :key="role.key" :class="['role',selected===role.key?'selected':'']" @tap="selected=role.key"><text class="role-icon">{{role.icon}}</text><text>{{role.label}}</text></view></view><view class="primary-btn submit" @tap="register">立即注册 →</view></view><text class="switch">已有账号？<text @tap="login">立即登录</text></text></view></template>
<script>import {callCloud,roleHome,saveUserSession} from '../../common/cloud.js';import {toast} from '../../common/mock.js';export default{data(){return{username:'',password:'',selected:'personal',roles:[{key:'personal',icon:'●',label:'个人端'},{key:'enterprise',icon:'▣',label:'企业端'},{key:'campus',icon:'⌂',label:'校园端'}]}},methods:{back(){uni.navigateBack()},login(){uni.navigateTo({url:'/pages/login/form'})},async register(){const username=this.username.trim();if(!username||!this.password)return toast('请输入用户名和密码');try{const check=await callCloud('user-check',{username});if(check.exists)return toast('用户名已注册');const result=await callCloud('user-register',{username,password:this.password,role:this.selected});saveUserSession({id:result.userId,username,role:this.selected,schoolId:'',points:1280});uni.showToast({title:'注册成功',icon:'success'});setTimeout(()=>uni.reLaunch({url:roleHome(result.role||this.selected)}),500)}catch(error){toast(error.message||'注册失败')}}}}</script>
<style lang="scss">@import '../../common/portal.scss';.auth-page{min-height:100vh;padding:24rpx 40rpx 48rpx;background:#f7faf9;box-sizing:border-box}.back{width:68rpx;height:68rpx;font-size:58rpx}.auth-icon{display:flex;align-items:center;justify-content:center;width:100rpx;height:100rpx;margin-top:78rpx;border-radius:24rpx;background:#56b36c;color:#00391a;font-size:44rpx}.auth-page .title{display:block;margin-top:36rpx;font-size:54rpx}.auth-page .subtitle{font-size:28rpx}.form{margin-top:66rpx}.label{display:block;margin:22rpx 8rpx 12rpx;color:#53615f;font-size:24rpx}.input{width:100%;height:112rpx;padding:0 28rpx;border:2rpx solid #d7dbda;border-radius:24rpx;background:#fff;box-sizing:border-box;font-size:27rpx}.roles{display:flex;gap:14rpx}.role{display:flex;flex:1;flex-direction:column;align-items:center;justify-content:center;height:148rpx;border:2rpx solid #d7dbda;border-radius:24rpx;color:#53615f;font-size:24rpx}.role.selected{border-color:#27ae60;background:#d6e6e3;color:#00391a}.role-icon{margin-bottom:12rpx;font-size:32rpx}.submit{height:112rpx;margin-top:58rpx;border-radius:24rpx;font-size:34rpx;font-weight:700}.switch{display:block;margin-top:34rpx;text-align:center;color:#53615f;font-size:25rpx}.switch text{color:#006d37}</style>
